<?php
use Moves\Services\Contacts; use Moves\Services\Finance; use Moves\Services\FinanceContext;
$e=static fn(mixed $v):string=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');
$search=is_string($_GET['busca']??null)?mb_substr(trim($_GET['busca']),0,180):''; $role=in_array($_GET['papel']??'', ['customer','supplier','both'],true)?$_GET['papel']:''; $type=in_array($_GET['tipo']??'', ['individual','company'],true)?$_GET['tipo']:''; $status=in_array($_GET['situacao']??'', ['active','inactive'],true)?$_GET['situacao']:''; $page=max(1,(int)($_GET['page']??1));
$result=['rows'=>[],'total'=>0,'pages'=>1,'page'=>1]; $service=null; $failed=false;
try{$service=new Contacts((int)FinanceContext::currentId());$result=$service->listing(compact('search','role','type','status','page'));}catch(Throwable $x){error_log('Realizze contacts view: '.$x->getMessage());$failed=true;}
$flash=$_SESSION['contacts_flash']??null;unset($_SESSION['contacts_flash']);
$mask=static function(?string $d):string{if(!$d)return 'Não informado';return strlen($d)===11?substr($d,0,3).'.***.***-'.substr($d,-2):substr($d,0,2).'.***.***/****-'.substr($d,-2);};
?>
<?php if(is_array($flash)):?><p class="finance-flash finance-flash-<?= $e($flash[0]) ?>" role="status"><?= $e($flash[1]) ?></p><?php endif;?>
<section class="card finance-workspace"><div class="finance-toolbar"><div><h2>Clientes e fornecedores</h2><p class="muted">Base unificada do contexto financeiro atual.</p></div><button class="primary" type="button" data-finance-open="contact-create">+ Novo contato</button></div>
<form class="receivables-filters" method="get"><input type="hidden" name="pagina" value="contatos"><label>Pesquisar<input name="busca" value="<?= $e($search) ?>" placeholder="Nome, fantasia ou documento"></label><label>Papel<select name="papel"><option value="">Todos</option><option value="customer"<?= $role==='customer'?' selected':'' ?>>Clientes</option><option value="supplier"<?= $role==='supplier'?' selected':'' ?>>Fornecedores</option><option value="both"<?= $role==='both'?' selected':'' ?>>Ambos</option></select></label><label>Tipo<select name="tipo"><option value="">Todos</option><option value="individual"<?= $type==='individual'?' selected':'' ?>>Pessoa física</option><option value="company"<?= $type==='company'?' selected':'' ?>>Pessoa jurídica</option></select></label><label>Situação<select name="situacao"><option value="">Todas</option><option value="active"<?= $status==='active'?' selected':'' ?>>Ativos</option><option value="inactive"<?= $status==='inactive'?' selected':'' ?>>Inativos</option></select></label><button class="primary">Filtrar</button></form>
<?php if($failed):?><div class="finance-empty"><h3>Não foi possível carregar os contatos</h3></div><?php elseif(!$result['rows']):?><div class="finance-empty"><h3>Nenhum contato encontrado</h3><p>Cadastre seu primeiro cliente ou fornecedor.</p></div><?php else:?><div class="finance-table-wrap" role="region" tabindex="0" aria-label="Clientes e fornecedores"><table class="finance-table"><caption class="finance-table-caption"><?= (int)$result['total'] ?> contato(s)</caption><thead><tr><th>Nome</th><th>Documento</th><th>Tipo</th><th>Papel</th><th>Contato</th><th>Situação</th><th>Ações</th></tr></thead><tbody>
<?php foreach($result['rows'] as $row):$summary=$service->financialSummary((int)$row['id']);?><tr><td><strong><?= $e($row['trade_name']?:$row['social_name']?:$row['legal_name']) ?></strong><small class="receivables-origin"><?= $e($row['legal_name']) ?></small></td><td><?= $e($mask($row['document_value'])) ?></td><td><?= $row['person_type']==='company'?'PJ':'PF' ?></td><td><?= $row['is_customer']&&$row['is_supplier']?'Cliente e fornecedor':($row['is_customer']?'Cliente':'Fornecedor') ?></td><td><?= $e($row['email']?:$row['mobile']?:$row['phone']?:'Não informado') ?></td><td><span class="finance-badge is-<?= $row['status']==='active'?'received':'cancelled' ?>"><?= $row['status']==='active'?'Ativo':'Inativo' ?></span></td><td class="finance-actions"><button type="button" data-finance-open="contact-view-<?= (int)$row['id'] ?>">Ver</button><button type="button" data-finance-open="contact-edit-<?= (int)$row['id'] ?>">Editar</button><form method="post" action="/minha-conta/contatos/status" data-finance-form><input type="hidden" name="csrf_token" value="<?= $e($csrf) ?>"><input type="hidden" name="id" value="<?= (int)$row['id'] ?>"><input type="hidden" name="active" value="<?= $row['status']==='active'?'0':'1' ?>"><button type="submit"><?= $row['status']==='active'?'Inativar':'Reativar' ?></button></form></td></tr>
<tr class="receivables-dialog-row"><td colspan="7"><dialog class="finance-dialog" id="contact-view-<?= (int)$row['id'] ?>"><div><header><h2><?= $e($row['legal_name']) ?></h2><button type="button" data-finance-close>×</button></header><p><?= (int)$summary['entries'] ?> recebimento(s) vinculado(s) · <?= $e(Finance::money((int)$summary['total_cents'])) ?></p><p><?= $e($row['notes']?:'Sem observações.') ?></p><footer><button type="button" data-finance-close>Fechar</button></footer></div></dialog><dialog class="finance-dialog" id="contact-edit-<?= (int)$row['id'] ?>"><form method="post" action="/minha-conta/contatos/atualizar" data-finance-form><header><h2>Editar contato</h2><button type="button" data-finance-close>×</button></header><input type="hidden" name="csrf_token" value="<?= $e($csrf) ?>"><input type="hidden" name="id" value="<?= (int)$row['id'] ?>"><?php $contact=$row;require __DIR__.'/../components/contact-fields.php';?><footer><button type="button" data-finance-close>Cancelar</button><button class="primary" type="submit">Salvar</button></footer></form></dialog></td></tr><?php endforeach;?></tbody></table></div><?php endif;?>
<?php if($result['pages']>1):?><nav class="receivables-pagination" aria-label="Páginas"><?php for($p=1;$p<=$result['pages'];$p++):?><a href="/minha-conta?<?= $e(http_build_query(['pagina'=>'contatos','busca'=>$search,'papel'=>$role,'tipo'=>$type,'situacao'=>$status,'page'=>$p])) ?>"<?= $p===$result['page']?' aria-current="page"':'' ?>><?= $p ?></a><?php endfor;?></nav><?php endif;?></section>
<dialog class="finance-dialog" id="contact-create"><form method="post" action="/minha-conta/contatos/salvar" data-finance-form><header><h2>Novo contato</h2><button type="button" data-finance-close>×</button></header><input type="hidden" name="csrf_token" value="<?= $e($csrf) ?>"><?php $contact=[];require __DIR__.'/../components/contact-fields.php';?><footer><button type="button" data-finance-close>Cancelar</button><button class="primary" type="submit">Cadastrar</button></footer></form></dialog>
